class Solution:
    def numberOfSets(self, n, maxDistance, roads):
        INF = float('inf')
        ans = 0
        for mask in range(1 << n):
            d = [[INF] * n for _ in range(n)]
            for i in range(n):
                if mask >> i & 1:
                    d[i][i] = 0
            for u, v, w in roads:
                if mask >> u & 1 and mask >> v & 1:
                    d[u][v] = min(d[u][v], w)
                    d[v][u] = min(d[v][u], w)
            for k in range(n):
                if not mask >> k & 1:
                    continue
                dk = d[k]
                for i in range(n):
                    dik = d[i][k]
                    if dik == INF:
                        continue
                    di = d[i]
                    for j in range(n):
                        if dik + dk[j] < di[j]:
                            di[j] = dik + dk[j]
            if all(d[i][j] <= maxDistance
                   for i in range(n) if mask >> i & 1
                   for j in range(n) if mask >> j & 1):
                ans += 1
        return ans

