class Solution {
public:
    int numberOfSets(int n, int maxDistance, vector<vector<int>>& roads) {
        int ans = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            vector<vector<long long>> d(n, vector<long long>(n, LLONG_MAX / 2));
            for (int i = 0; i < n; i++)
                if (mask >> i & 1) d[i][i] = 0;
            for (auto& r : roads)
                if (mask >> r[0] & 1 && mask >> r[1] & 1) {
                    d[r[0]][r[1]] = min(d[r[0]][r[1]], (long long)r[2]);
                    d[r[1]][r[0]] = min(d[r[1]][r[0]], (long long)r[2]);
                }
            for (int k = 0; k < n; k++) {
                if (!(mask >> k & 1)) continue;
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++)
                        d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
            }
            bool ok = true;
            for (int i = 0; i < n && ok; i++)
                if (mask >> i & 1)
                    for (int j = 0; j < n; j++)
                        if (mask >> j & 1 && d[i][j] > maxDistance) { ok = false; break; }
            ans += ok;
        }
        return ans;
    }
};

