import heapq
class Solution:
    def numberOfSets(self, n, maxDistance, roads):
        ans = 0
        for mask in range(1 << n):
            adj = [[] for _ in range(n)]
            for u, v, w in roads:
                if mask >> u & 1 and mask >> v & 1:
                    adj[u].append((v, w))
                    adj[v].append((u, w))
            ok = True
            for src in range(n):
                if not mask >> src & 1:
                    continue
                dist = [float('inf')] * n
                dist[src] = 0
                pq = [(0, src)]
                while pq:
                    du, u = heapq.heappop(pq)
                    if du > dist[u]:
                        continue
                    for v, w in adj[u]:
                        if du + w < dist[v]:
                            dist[v] = du + w
                            heapq.heappush(pq, (dist[v], v))
                for j in range(n):
                    if mask >> j & 1 and dist[j] > maxDistance:
                        ok = False
            ans += ok
        return ans

