class Solution {
    public int numberOfSets(int n, int maxDistance, int[][] roads) {
        int ans = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            List<List<int[]>> adj = new ArrayList<>();
            for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
            for (int[] r : roads)
                if ((mask >> r[0] & 1) != 0 && (mask >> r[1] & 1) != 0) {
                    adj.get(r[0]).add(new int[]{r[1], r[2]});
                    adj.get(r[1]).add(new int[]{r[0], r[2]});
                }
            boolean ok = true;
            for (int s = 0; s < n && ok; s++) {
                if ((mask >> s & 1) == 0) continue;
                long[] dist = new long[n];
                java.util.Arrays.fill(dist, Long.MAX_VALUE / 2);
                PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
                dist[s] = 0;
                pq.add(new long[]{0, s});
                while (!pq.isEmpty()) {
                    long[] top = pq.poll();
                    int u = (int) top[1];
                    if (top[0] > dist[u]) continue;
                    for (int[] e : adj.get(u))
                        if (top[0] + e[1] < dist[e[0]]) {
                            dist[e[0]] = top[0] + e[1];
                            pq.add(new long[]{dist[e[0]], e[0]});
                        }
                }
                for (int j = 0; j < n; j++)
                    if ((mask >> j & 1) != 0 && dist[j] > maxDistance) { ok = false; break; }
            }
            if (ok) ans++;
        }
        return ans;
    }
}

